    out = [row[:] for row in grid]

    # Find 3x3 motifs consisting of a 3 border and a 2 center.
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[rr][cc] == 3
                for rr in range(r - 1, r + 2)
                for cc in range(c - 1, c + 2)
                if (rr, cc) != (r, c)
            ):
                centers.append((r, c))

    row_bars = [r for r in range(h) if sum(v == 2 for v in grid[r]) >= w // 2]
    col_bars = [c for c in range(w) if sum(grid[r][c] == 2 for r in range(h)) >= h // 2]

    # Motifs project perpendicular to the long 2-lines.
    horizontal_projection = len(col_bars) >= len(row_bars)

    def ray(r, c):
        if grid[r][c] == 0:
            out[r][c] = 1

    for r, c in centers:
        if horizontal_projection:
            for x in range(w):
                ray(r, x)
            # The motif spreads across each other vertical bar it meets.
            for x in col_bars:
                if x == c:
                    continue
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        rr, cc = r + dr, x + dc
                        if (dr, dc) != (0, 0) and 0 <= rr < h and 0 <= cc < w:
                            if grid[rr][cc] != 3:
                                out[rr][cc] = 1
        else:
            for y in range(h):
                ray(y, c)
            # The motif spreads across each other horizontal bar it meets.
            for y in row_bars:
                if y == r:
                    continue
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        rr, cc = y + dr, c + dc
                        if (dr, dc) != (0, 0) and 0 <= rr < h and 0 <= cc < w:
                            if grid[rr][cc] != 3:
                                out[rr][cc] = 1

    return out
